CREATE TABLE IF NOT EXISTS villages (id uuid PRIMARY KEY, name text NOT NULL, code text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, data jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, village_id uuid REFERENCES villages(id), name text NOT NULL, username text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('SUPER_ADMIN','ADMIN','OPERATOR','PIMPINAN')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), CHECK(role='SUPER_ADMIN' OR village_id IS NOT NULL));
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, scope_id uuid REFERENCES villages(id));
CREATE TABLE IF NOT EXISTS login_attempts (key text PRIMARY KEY, attempts integer NOT NULL, reset_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS residents (id uuid PRIMARY KEY, village_id uuid NOT NULL REFERENCES villages(id), nik varchar(16) NOT NULL CHECK(nik ~ '^[0-9]{16}$'), name text NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_by uuid REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(village_id,nik));
CREATE INDEX IF NOT EXISTS residents_search_idx ON residents(village_id,lower(name));
CREATE TABLE IF NOT EXISTS officials (id uuid PRIMARY KEY, village_id uuid NOT NULL REFERENCES villages(id), name text NOT NULL, active boolean NOT NULL DEFAULT true, data jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS letter_types (id uuid PRIMARY KEY, name text NOT NULL, code text NOT NULL, slug text NOT NULL UNIQUE, category text NOT NULL, description text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, fields jsonb NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS templates (id uuid PRIMARY KEY, type_id uuid NOT NULL REFERENCES letter_types(id), version integer NOT NULL, storage_path text NOT NULL, file_name text NOT NULL, placeholders jsonb NOT NULL DEFAULT '[]', errors jsonb NOT NULL DEFAULT '[]', active boolean NOT NULL DEFAULT false, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(type_id,version));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_template ON templates(type_id) WHERE active=true;
ALTER TABLE templates ADD COLUMN IF NOT EXISTS deleted_at timestamptz;
CREATE TABLE IF NOT EXISTS counters (village_id uuid NOT NULL REFERENCES villages(id), type_id uuid NOT NULL REFERENCES letter_types(id), year integer NOT NULL, last_sequence integer NOT NULL DEFAULT 0 CHECK(last_sequence>=0), PRIMARY KEY(village_id,type_id,year));
CREATE TABLE IF NOT EXISTS letters (id uuid PRIMARY KEY, village_id uuid NOT NULL REFERENCES villages(id), resident_id uuid NOT NULL REFERENCES residents(id), type_id uuid NOT NULL REFERENCES letter_types(id), official_id uuid REFERENCES officials(id), template_id uuid REFERENCES templates(id), status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PREVIEW','ISSUE_PENDING','ISSUED','CANCELLED')), number text, sequence integer, issue_year integer, form_data jsonb NOT NULL DEFAULT '{}', snapshot jsonb, pdf_path text, preview_path text, error text, cancel_reason text, generation_token uuid, generation_started timestamptz, created_by uuid NOT NULL REFERENCES users(id), issued_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), issued_at timestamptz, UNIQUE(village_id,type_id,issue_year,sequence));
ALTER TABLE letters ADD COLUMN IF NOT EXISTS companion_pdf_path text;
CREATE INDEX IF NOT EXISTS letters_scope_idx ON letters(village_id,created_at DESC);
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY, village_id uuid REFERENCES villages(id), user_id uuid REFERENCES users(id), actor text NOT NULL, action text NOT NULL, target_type text NOT NULL, target_id uuid, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_scope_idx ON audit_logs(village_id,created_at DESC);
CREATE TABLE IF NOT EXISTS settings (id text PRIMARY KEY, data jsonb NOT NULL);
